+.media{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:
+    radial-gradient(700px 360px at 30% 20%, rgba(230,57,70,.24), transparent 55%),
+    linear-gradient(135deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
+  overflow:hidden;
+  min-height:240px;
+  position:relative;
+}
+.media::after{
+  content:"";
+  position:absolute;
+  inset:0;
+  background:
+    repeating-linear-gradient(90deg, rgba(255,255,255,.05) 0 1px, transparent 1px 10px);
+  opacity:.14;
+  mix-blend-mode:overlay;
+}
+.media .label{
+  position:absolute;
+  left:16px;
+  bottom:16px;
+  padding:10px 12px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.35);
+  backdrop-filter:blur(10px);
+  font-family:var(--font-display);
+  text-transform:uppercase;
+  letter-spacing:.12em;
+  font-size:12px;
+}
+
+.cta-band{
+  border-radius:calc(var(--radius) + 4px);
+  border:1px solid rgba(255,255,255,.12);
+  background:
+    radial-gradient(900px 420px at 18% 25%, rgba(255,0,0,.28), transparent 55%),
+    radial-gradient(700px 420px at 70% 15%, rgba(230,57,70,.22), transparent 55%),
+    linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
