+}
+.cta-band h2{
+  margin:0;
+  font-family:var(--font-display);
+  text-transform:uppercase;
+  letter-spacing:.06em;
+  font-size:30px;
+  line-height:1.05;
+}
+.cta-band p{margin:10px 0 0; color:rgba(243,244,246,.78); line-height:1.7; max-width:72ch}
+.cta-band .actions{display:flex; flex-wrap:wrap; gap:10px; margin-top:16px}
+
+/* Carousel */
+.carousel{
+  border-radius:calc(var(--radius) + 4px);
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  overflow:hidden;
+  position:relative;
+  box-shadow:var(--shadow-soft);
+}
+.carousel-track{
+  display:flex;
+  transition:transform .5s cubic-bezier(.2,.8,.2,1);
+  will-change:transform;
+}
+.slide{
+  min-width:100%;
+  aspect-ratio:16/9;
+  position:relative;
+  background:
+    radial-gradient(900px 520px at 30% 20%, rgba(230,57,70,.28), transparent 55%),
+    radial-gradient(700px 520px at 75% 35%, rgba(255,0,0,.16), transparent 60%),
+    linear-gradient(135deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
+}
+.slide::after{
+  content:"";
+  position:absolute; inset:0;
+  background:linear-gradient(180deg, rgba(0,0,0,.10), rgba(0,0,0,.55));
+  pointer-events:none;
+}
+.slide-inner{position:absolute; inset:0; display:flex; align-items:flex-end; padding:20px;}
+.slide-caption{
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.38);
+  backdrop-filter:blur(10px);
+  border-radius:16px;
+  padding:14px 14px;
+  max-width:72ch;
+}
+.slide-caption .title{
+  font-family:var(--font-display);
+  letter-spacing:.08em;
+  text-transform:uppercase;
+  font-size:16px;
+  margin:0 0 6px;
+}
+.slide-caption .desc{margin:0; color:rgba(243,244,246,.78); line-height:1.55}
+.carousel-controls{
+  position:absolute; inset:0;
+  display:flex; align-items:center; justify-content:space-between;
+  padding:0 12px;
+  pointer-events:none;
+}
+.icon-btn{
+  pointer-events:auto;
+  width:42px; height:42px;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.35);
+  backdrop-filter:blur(10px);
+  color:#fff;
+  display:inline-flex; align-items:center; justify-content:center;
+  cursor:pointer;
+  transition:transform .12s ease, background .12s ease, border-color .12s ease;
+}
+.icon-btn:hover{transform:translateY(-1px); background:rgba(0,0,0,.55); border-color:rgba(255,255,255,.18)}
+.icon-btn:active{transform:translateY(0)}
+.icon-btn:focus-visible{outline:none; box-shadow:var(--ring)}
+.carousel-dots{
+  position:absolute; left:50%; transform:translateX(-50%);
+  bottom:10px;
+  display:flex; gap:8px;
+}
+.dot{
+  width:10px; height:10px;
+  border-radius:99px;
+  border:1px solid rgba(255,255,255,.18);
+  background:rgba(255,255,255,.10);
+  cursor:pointer;
+}
+.dot[aria-current="true"]{background:rgba(230,57,70,.95); border-color:rgba(255,255,255,.22)}
+
+/* Toggle pills */
+.pillbar{
+  display:inline-flex;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  border-radius:999px;
+  padding:6px;
+  gap:6px;
+}
+.pill{
+  padding:10px 12px;
+  border-radius:999px;
+  border:1px solid transparent;
+  background:transparent;
+  color:rgba(243,244,246,.85);
+  font-family:var(--font-display);
+  text-transform:uppercase;
+  letter-spacing:.10em;
+  cursor:pointer;
+}
+.pill[aria-pressed="true"]{
+  background:rgba(230,57,70,.18);
+  border-color:rgba(230,57,70,.35);
+  color:#fff;
+}
+.pill:focus-visible{outline:none; box-shadow:var(--ring)}
+
+/* Table */
+.table-wrap{overflow:auto; border-radius:var(--radius); border:1px solid rgba(255,255,255,.10); box-shadow:var(--shadow-soft)}
+table{width:100%; border-collapse:collapse; min-width:620px; background:rgba(255,255,255,.03)}
+th,td{padding:14px 14px; text-align:left; border-bottom:1px solid rgba(255,255,255,.08)}
+th{
+  font-family:var(--font-display);
+  text-transform:uppercase;
+  letter-spacing:.10em;
+  font-size:13px;
+  color:rgba(243,244,246,.86);
+  background:rgba(0,0,0,.32);
+}
+tr:hover td{background:rgba(255,255,255,.03)}
+
+/* Instructor grid */
+.filter-row{display:flex; flex-wrap:wrap; gap:10px; align-items:center; justify-content:space-between;}
+.select{
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.22);
+  color:rgba(243,244,246,.92);
+}
+.select:focus-visible{outline:none; box-shadow:var(--ring)}
+.grid{display:grid; gap:16px}
+.instructor{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+  box-shadow:var(--shadow-soft);
+  overflow:hidden;
+  transform:translateZ(0);
+}
+.instructor .photo{
+  height:160px;
+  background:
+    radial-gradient(900px 480px at 30% 25%, rgba(230,57,70,.30), transparent 55%),
+    linear-gradient(135deg, rgba(255,255,255,.07), rgba(255,255,255,.02));
+  position:relative;
+}
+.instructor .photo::after{
+  content:"";
+  position:absolute; inset:0;
+  background:repeating-linear-gradient(90deg, rgba(255,255,255,.05) 0 1px, transparent 1px 12px);
