+}
+.instructor .body{padding:16px}
+.instructor .name{font-family:var(--font-display); text-transform:uppercase; letter-spacing:.08em; font-size:18px; margin:0}
+.instructor .meta{margin:6px 0 12px; color:var(--muted);}
+.instructor .actions{display:flex; gap:10px}
+.fade-enter{animation:fadeIn .26s ease both}
+@keyframes fadeIn{from{opacity:0; transform:translateY(6px)}to{opacity:1; transform:translateY(0)}}
+
+/* Accordion */
+.accordion{display:flex; flex-direction:column; gap:10px}
+.acc-item{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:rgba(255,255,255,.03);
+  overflow:hidden;
+}
+.acc-btn{
+  width:100%;
+  text-align:left;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  padding:16px 16px;
+  background:transparent;
+  border:0;
+  color:#fff;
+  cursor:pointer;
+}
+.acc-btn .q{
+  font-family:var(--font-display);
+  text-transform:uppercase;
+  letter-spacing:.06em;
+  font-size:16px;
+}
+.acc-btn:focus-visible{outline:none; box-shadow:var(--ring)}
+.acc-panel{max-height:0; overflow:hidden; transition:max-height .3s ease;}
+.acc-panel-inner{padding:0 16px 16px; color:rgba(243,244,246,.78); line-height:1.7}
+.chev{width:18px; height:18px; opacity:.85; transition:transform .2s ease}
+.acc-item[data-open="true"] .chev{transform:rotate(180deg)}
+
+/* Newsletter */
+.form-row{display:flex; gap:10px; flex-wrap:wrap; align-items:flex-start;}
+.input{
+  flex:1 1 260px;
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.22);
+  color:rgba(243,244,246,.92);
+}
+.input:focus-visible{outline:none; box-shadow:var(--ring)}
+.help{margin:8px 0 0; font-size:13px; color:rgba(243,244,246,.70)}
+.help.error{color:rgba(255,88,88,.95)}
+.help.success{color:rgba(104,255,170,.92)}
+
+footer{
+  border-top:1px solid rgba(255,255,255,.10);
+  background:rgba(0,0,0,.28);
+}
+.footer-inner{padding:38px 0; display:grid; gap:22px}
+.footer-grid{display:grid; gap:18px}
+.footer-col h4{margin:0 0 10px; font-family:var(--font-display); text-transform:uppercase; letter-spacing:.10em; font-size:14px}
+.footer-col a{display:block; padding:6px 0; color:rgba(243,244,246,.75)}
+.footer-col a:hover{color:#fff}
+.footer-bottom{display:flex; flex-wrap:wrap; gap:12px; align-items:center; justify-content:space-between; padding-top:12px; border-top:1px solid rgba(255,255,255,.08); color:rgba(243,244,246,.65)}
+
+/* Dialog */
+.dialog-backdrop{position:fixed; inset:0; background:rgba(0,0,0,.62); display:none; align-items:center; justify-content:center; padding:20px; z-index:2000;}
+.dialog{
+  max-width:560px; width:100%;
+  border-radius:calc(var(--radius) + 4px);
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(20,20,22,.98), rgba(10,10,12,.98));
+  box-shadow:var(--shadow);
+  overflow:hidden;
+}
+.dialog header{padding:18px 18px 0}
+.dialog header h3{margin:0; font-family:var(--font-display); text-transform:uppercase; letter-spacing:.10em;}
+.dialog header p{margin:8px 0 0; color:rgba(243,244,246,.72); line-height:1.6}
+.dialog .content{padding:14px 18px 18px; display:grid; gap:10px}
+.dialog .regions{display:grid; gap:8px; grid-template-columns:repeat(2, minmax(0,1fr));}
+.region{
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  cursor:pointer;
+  display:flex; align-items:center; justify-content:space-between;
+}
+.region:hover{background:rgba(255,255,255,.06)}
+.region strong{font-family:var(--font-display); text-transform:uppercase; letter-spacing:.08em; font-size:14px}
+.region span{color:rgba(243,244,246,.65); font-size:13px}
+.dialog .footer{padding:0 18px 18px; display:flex; justify-content:flex-end;}
+.dialog-backdrop[data-open="true"]{display:flex}
+
+/* Responsive */
+@media (min-width: 860px){
+  .nav-links{display:flex}
+  .mobile-toggle{display:none}
+  .hero-inner{grid-template-columns:1.2fr .8fr}
+  .grid-2{grid-template-columns:repeat(2, minmax(0,1fr))}
+  .grid-3{grid-template-columns:repeat(3, minmax(0,1fr))}
+  .split{grid-template-columns:1.05fr .95fr}
+  .grid{grid-template-columns:repeat(3, minmax(0,1fr))}
+  .footer-grid{grid-template-columns:repeat(4, minmax(0,1fr))}
+}
+@media (min-width: 1120px){
+  .h1{font-size:52px}
+  .cta-band h2{font-size:34px}
+}
+
+@media (prefers-reduced-motion: reduce){
+  .carousel-track{transition:none}
+  .btn,.icon-btn{transition:none}
+  .fade-enter{animation:none}
+  .acc-panel{transition:none}
+}
+
*** End Patch
